// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"obidoxim":{"wirkmechanismus":"Macht das durch das Gift blockierte Enzym, das den Nervenbotenstoff Acetylcholin abbaut, wieder funktionsfähig. Organophosphate hemmen die Acetylcholinesterase durch Phosphorylierung; dadurch häuft sich Acetylcholin an, und es kommt zu Muskelzuckungen, Lähmungen und Atemversagen. Obidoxim löst die Phosphorylgruppe vom Enzym und reaktiviert es, vor allem an der Verbindung zwischen Nerv und Muskel. Die Wirkung ist umso besser, je früher es gegeben wird, weil das gehemmte Enzym mit der Zeit «altert» und dann nicht mehr reaktivierbar ist.","nebenwirkungen":{"unbekannt":["Hitzegefühl, Gesichtsrötung, Kribbeln","Kälte- oder Mentholgefühl in Mund und Nase","Blutdruckanstieg, Herzrasen, Herzrhythmusstörungen","Erhöhte Leberwerte, Gelbsucht (bei hohen Dosen)"]},"schwangerschaft":"Keine ausreichenden Daten. Bei lebensbedrohlicher Vergiftung wird Obidoxim trotzdem eingesetzt, weil der Nutzen überwiegt.","stillzeit":"Keine Daten; Entscheidung nach ärztlicher Abwägung.","hinweise":["Wird durch Notärztinnen und Notärzte oder im Spital verabreicht, so früh wie möglich nach der Vergiftung.","Immer zusammen mit ausreichend Atropin geben; Obidoxim ersetzt Atropin nicht."],"darreichung":["Injektionslösung (Ampullen)"]},"obinutuzumab":{"wirkmechanismus":"Markiert bestimmte weisse Blutkörperchen (B-Zellen), damit das Immunsystem sie zerstört – auch die bösartigen B-Zellen bei Leukämie und Lymphom. Obinutuzumab ist ein humanisierter monoklonaler IgG1-Antikörper vom Typ II gegen das Oberflächenmolekül CD20. Durch die Veränderung der Zuckerketten am Fc-Teil (Glykomodifikation) ist die antikörperabhängige zelluläre Zytotoxizität und Phagozytose verstärkt; zudem löst er direkt den Zelltod aus. Die komplementvermittelte Zellzerstörung ist geringer als bei Rituximab.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen (Fieber, Schüttelfrost, Blutdruckabfall, Übelkeit)","Neutropenie (Mangel an weissen Blutkörperchen)","Thrombozytopenie (Mangel an Blutplättchen)","Anämie (Blutarmut)","Infektionen der oberen Atemwege, Lungenentzündung, Nasennebenhöhlenentzündung","Husten","Durchfall, Verstopfung","Fieber"],"haeufig":["Tumorlysesyndrom","Febrile Neutropenie (Fieber bei Mangel an weissen Blutkörperchen)","Herpes-Infektionen, Gürtelrose","Harnwegsinfekte","Vorhofflimmern","Bluthochdruck","Hyperurikämie (erhöhte Harnsäure)"],"gelegentlich":["Reaktivierung einer Hepatitis B"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Magen-Darm-Perforation (Durchbruch)","Verschlechterung bestehender Herzkrankheiten"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar: Der Antikörper geht über die Plazenta und kann beim Neugeborenen die B-Zellen vermindern. Frauen im gebärfähigen Alter verhüten während der Behandlung und 18 Monate danach.","stillzeit":"Während der Behandlung und 18 Monate nach der letzten Dosis nicht stillen.","hinweise":["Vor jeder Infusion gibt es Medikamente gegen Infusionsreaktionen (z. B. Kortison, Paracetamol, Antihistaminikum).","Zu Beginn viel trinken (Vorbeugung eines Tumorlysesyndroms).","Fieber, Infektzeichen, Blutungen oder neue neurologische Beschwerden (Verwirrtheit, Seh- oder Sprachstörungen) sofort melden.","Regelmässige Blutbildkontrollen; keine Lebendimpfungen während und nach der Behandlung ohne ärztliche Freigabe."],"darreichung":["Infusionskonzentrat"]},"ocrelizumab":{"wirkmechanismus":"Entfernt eine Untergruppe von Abwehrzellen (B-Lymphozyten), die bei Multipler Sklerose an den Angriffen auf die Nervenhüllen beteiligt sind. Ocrelizumab ist ein humanisierter monoklonaler Antikörper gegen das Oberflächenmerkmal CD20 auf B-Zellen. Durch Antikörper-abhängige Zelltötung und Komplementaktivierung werden diese Zellen abgebaut, während Stammzellen und Plasmazellen erhalten bleiben. Die B-Zellen bleiben über Monate vermindert.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege, Nasen-Rachen-Entzündung, Grippe","Infusions- oder Injektionsreaktionen (Juckreiz, Ausschlag, Halsreizung, Hitzegefühl, Fieber, Kopfschmerzen, Blutdruckabfall)","Verminderte Immunglobulin-M-Spiegel"],"haeufig":["Nasennebenhöhlenentzündung, Bronchitis, Magen-Darm-Infekt","Lippenherpes, Gürtelrose","Konjunktivitis (Bindehautentzündung), Zellulitis","Husten, Katarrh","Neutropenie","Verminderte Immunglobulin-G-Spiegel"],"unbekannt":["Spät auftretende Neutropenie","Progressive multifokale Leukenzephalopathie (PML)","Hepatitis-B-Reaktivierung","Schwere Infektionen bei Hypogammaglobulinämie","Immunvermittelte Kolitis (Darmentzündung)"]},"schwangerschaft":"Vorsichtshalber vermeiden; Frauen im gebärfähigen Alter verhüten während und noch mehrere Monate nach der letzten Gabe (Dauer gemäss Fachinformation). Bei Exposition im Mutterleib können beim Neugeborenen die B-Zellen vermindert sein – Lebendimpfungen erst nach Kontrolle.","stillzeit":"Nur sehr geringe Mengen gehen in die Muttermilch über und werden vom Säugling kaum aufgenommen; Stillen nach ärztlicher Abwägung möglich.","hinweise":["Vor Beginn auf Hepatitis B testen und den Impfstatus vervollständigen lassen.","Nach der Gabe mindestens 1 Stunde auf Reaktionen beobachten; auch Reaktionen bis 24 Stunden später melden.","Neue Sehstörungen, Lähmungen, Verwirrtheit oder Wesensveränderungen sofort ärztlich melden (PML).","Regelmässige Krebsvorsorge (insbesondere Brust) wahrnehmen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung zur subkutanen Anwendung"]},"octenidin":{"wirkmechanismus":"Tötet Krankheitserreger auf Haut, Schleimhaut und in Wunden innert etwa einer Minute ab. Octenidin ist ein kationisches (positiv geladenes) Tensid, das sich an die negativ geladenen Zellwände und Membranen von Mikroorganismen bindet und diese zerstört; der Zusatzstoff Phenoxyethanol verstärkt die Wirkung. Wirksam ist es gegen Bakterien (auch MRSA), Pilze sowie behüllte Viren wie Herpes-simplex- und Hepatitis-B-Viren. Octenidin wird über Haut, Schleimhaut und Wunden praktisch nicht in den Körper aufgenommen.","nebenwirkungen":{"selten":["Brennen, Rötung, Juckreiz und Wärmegefühl an der Anwendungsstelle"],"sehrSelten":["Kontaktallergische Reaktionen, z. B. vorübergehende Rötung"],"unbekannt":["Vorübergehend bitterer Geschmack nach Anwendung in der Mundhöhle","Anhaltende Schwellung, Entzündung und Gewebeschäden nach Einspritzen unter Druck in tiefe Wunden"]},"schwangerschaft":"Nach bisherigen Erfahrungen möglich; Octenidin wird praktisch nicht in den Körper aufgenommen.","stillzeit":"Möglich, da praktisch keine Aufnahme in den Körper erfolgt; nicht unmittelbar vor dem Stillen auf die Brust auftragen.","hinweise":["Mindestens 1 Minute einwirken lassen.","Nie mit einer Spritze oder unter Druck in tiefe Wunden einspritzen.","Nicht gleichzeitig mit Iod-Präparaten (z. B. Betadine) an derselben Stelle verwenden."],"darreichung":["Lösung","Spray"]},"octreotid":{"wirkmechanismus":"Bremst die Ausschüttung verschiedener Hormone, vor allem von Wachstumshormon und von Hormonen des Magen-Darm-Trakts. Octreotid ist ein synthetisches, länger wirksames Abbild des körpereigenen Somatostatins und bindet vor allem an die Somatostatin-Rezeptoren SSTR2 und SSTR5. Dadurch werden Wachstumshormon und IGF-1 sowie Insulin, Glukagon, Serotonin, VIP und Gastrin vermindert freigesetzt; bei Akromegalie und hormonbildenden Tumoren lassen so Beschwerden wie Flush und Durchfall nach. Zudem kann es das Wachstum neuroendokriner Tumoren bremsen. Die Depotform gibt den Wirkstoff über etwa 4 Wochen ab.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Bauchschmerzen, Übelkeit, Verstopfung, Blähungen","Kopfschmerzen","Gallensteine (Cholelithiasis)","Erhöhter Blutzucker (Hyperglykämie)","Schmerzen und Reaktionen an der Einstichstelle"],"haeufig":["Unterzuckerung (Hypoglykämie), gestörte Glukosetoleranz","Schilddrüsenunterfunktion, Schilddrüsenfunktionsstörung","Bradykardie (langsamer Puls)","Schwindel","Appetitlosigkeit, Erbrechen, Völlegefühl, Fettstuhl, Verfärbung des Stuhls","Gallenblasenentzündung, Gallengries, erhöhtes Bilirubin, erhöhte Leberwerte","Haarausfall, Juckreiz, Hautausschlag","Atemnot"],"gelegentlich":["Dehydratation (Flüssigkeitsmangel)","Beschleunigter Puls (Tachykardie)"],"unbekannt":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Akute Hepatitis, Gallenstau, Gelbsucht","Thrombozytopenie (Mangel an Blutplättchen)","Herzrhythmusstörungen","Anaphylaxie, Nesselsucht"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, die Erfahrungen sind begrenzt. Bei Akromegalie kann sich die Fruchtbarkeit unter der Behandlung erholen – Verhütung besprechen.","stillzeit":"Es ist nicht bekannt, ob Octreotid in die Muttermilch übergeht; während der Behandlung nicht stillen.","hinweise":["Injektionslösung möglichst zwischen den Mahlzeiten oder vor dem Schlafengehen spritzen (weniger Magen-Darm-Beschwerden) und die Einstichstelle wechseln.","Die Depotform wird alle 4 Wochen von Fachpersonen tief in den Gesässmuskel gespritzt.","Regelmässige Kontrollen von Blutzucker, Schilddrüse und Gallenblase (Ultraschall); bei Gallenkoliken, Gelbsucht oder starken Oberbauchschmerzen ärztlich abklären."],"darreichung":["Injektionslösung (unter die Haut oder in die Vene)","Pulver und Lösungsmittel für eine Depot-Injektionssuspension (in den Muskel)"]},"odevixibat":{"wirkmechanismus":"Lindert den Juckreiz und entlastet die Leber, indem es die Gallensäuren im Körper senkt. Odevixibat hemmt im letzten Dünndarmabschnitt (Ileum) den Transporter IBAT, über den normalerweise der grösste Teil der Gallensäuren in den Körper zurückgeholt wird. Mehr Gallensäuren werden so mit dem Stuhl ausgeschieden und ihr Spiegel im Blut sinkt. Der Wirkstoff wird kaum ins Blut aufgenommen und wirkt fast nur im Darm.","nebenwirkungen":{"haeufig":["Durchfall, auch mit Blutbeimengung","Weicher Stuhl","Bauchschmerzen","Lebervergrösserung (Hepatomegalie)"],"unbekannt":["Erhöhte Leberwerte und Bilirubin","Mangel an fettlöslichen Vitaminen (A, D, E, K)"]},"schwangerschaft":"Keine Erfahrungen; Tierversuche zeigten Fehlbildungen. Nicht empfohlen; Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Nur nach ärztlicher Abwägung; wegen der minimalen Aufnahme ins Blut ist ein Übergang in die Muttermilch kaum zu erwarten.","hinweise":["Morgens einnehmen; Kapseln mit Granulat können geöffnet und der Inhalt auf etwas weiche Nahrung (z. B. Joghurt, Apfelmus) gestreut werden.","Bei anhaltendem Durchfall ärztlichen Rat einholen; fettlösliche Vitamine und Leberwerte werden regelmässig kontrolliert."],"darreichung":["Hartkapseln","Kapseln mit Granulat zum Öffnen"]},"ofatumumab":{"wirkmechanismus":"Vermindert bestimmte Abwehrzellen (B-Lymphozyten), die an den Entzündungsherden bei MS beteiligt sind. Ofatumumab ist ein vollständig humaner monoklonaler IgG1-Antikörper gegen das Oberflächenmolekül CD20 auf B-Zellen. Die Bindung löst komplementabhängige und antikörperabhängige zelluläre Zytotoxizität aus, wodurch die B-Zellen abgebaut werden. Die monatliche Gabe unter die Haut hält die B-Zellen dauerhaft tief.","nebenwirkungen":{"sehrHaeufig":["Infekte der oberen Atemwege","Harnwegsinfekte","Injektionsbedingte Allgemeinreaktionen (Fieber, Kopfschmerzen, Muskelschmerzen, Schüttelfrost, Müdigkeit), vor allem nach der ersten Injektion","Reaktionen an der Einstichstelle (Rötung, Schmerzen, Juckreiz, Schwellung)"],"haeufig":["Lippenherpes","Verminderter IgM-Spiegel im Blut"],"unbekannt":["Hepatitis-B-Reaktivierung"]},"schwangerschaft":"Während der Behandlung und bis 6 Monate nach der letzten Dosis zuverlässig verhüten. Nach Anwendung in der Schwangerschaft kann das Neugeborene einen B-Zell-Mangel haben; Lebendimpfungen beim Säugling erst nach ärztlicher Rücksprache.","stillzeit":"Antikörper gehen nur in geringer Menge in die Muttermilch über; Anwendung in der Stillzeit nach ärztlicher Abwägung möglich.","hinweise":["Erste Injektion unter Anleitung einer Fachperson; Fieber, Kopf- und Gliederschmerzen nach der ersten Dosis sind häufig und meist harmlos.","Pen im Kühlschrank lagern; vor der Injektion auf Raumtemperatur kommen lassen.","Vor Beginn Hepatitis-B-Test und Immunglobulinbestimmung; Infektzeichen rasch ärztlich melden."],"darreichung":["Injektionslösung im Fertigpen"]},"ofloxacin":{"wirkmechanismus":"Tötet Bakterien ab, indem es ihre Vermehrung blockiert. Ofloxacin hemmt die bakteriellen Enzyme DNA-Gyrase (Topoisomerase II) und Topoisomerase IV, die zum Entwinden, Kopieren und Trennen der Erbsubstanz (DNA) nötig sind. Die Wirkung ist bakterizid und umfasst viele gramnegative und grampositive Erreger. Nach Anwendung am Auge gelangen nur sehr geringe Mengen ins Blut.","nebenwirkungen":{"haeufig":["Augenbrennen, Augenreizung und Augenbeschwerden"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Gesichts- oder Lidschwellung","Bindehaut- oder Hornhautentzündung, Augenrötung, Augenschmerzen","Verschwommenes Sehen, Lichtempfindlichkeit","Fremdkörpergefühl, Tränenfluss, trockenes Auge, Juckreiz","Schwindel, Übelkeit","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"]},"schwangerschaft":"Keine ausreichenden Daten; Fluorchinolone schädigen im Tierversuch den Gelenkknorpel. Am Auge nur nach ärztlicher Abwägung anwenden.","stillzeit":"Ofloxacin geht in die Muttermilch über; nach Anwendung am Auge ist die Menge sehr gering. Nur nach ärztlicher Abwägung.","hinweise":["Tropferspitze nicht mit Auge, Fingern oder anderen Flächen in Berührung bringen.","So lange wie verordnet anwenden, aber nicht länger als nötig (Resistenzgefahr).","Nach dem Eintropfen kann die Sicht kurz verschwommen sein – erst danach Auto fahren."],"darreichung":["Augentropfen","Augensalbe"]},"olaflur":{"wirkmechanismus":"Stärkt den Zahnschmelz und macht ihn widerstandsfähiger gegen Säureangriffe der Kariesbakterien. Das Aminfluorid Olaflur verteilt sich dank seiner oberflächenaktiven Eigenschaften rasch als gleichmässiger Film auf den Zähnen. Das freigesetzte Fluorid bildet eine Calciumfluorid-Deckschicht und wird als Fluorapatit in den Schmelz eingebaut, der weniger säurelöslich ist. Zudem fördert Fluorid die Remineralisation beginnender Schmelzschäden und hemmt den Stoffwechsel der Kariesbakterien.","nebenwirkungen":{"sehrSelten":["Abschilferung, Rötung oder oberflächliche Erosionen der Mundschleimhaut","Brennen, Juckreiz oder Taubheitsgefühl im Mund","Zahnfleischentzündung (Gingivitis) und Mundschleimhautentzündung (Stomatitis)","Geschmacksstörungen, Mundtrockenheit","Übelkeit und Erbrechen (beim Verschlucken grösserer Mengen)","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Bei bestimmungsgemässer Anwendung im Mund sind keine Risiken bekannt; das Gel nicht schlucken.","stillzeit":"Bei bestimmungsgemässer Anwendung sind keine Risiken für das gestillte Kind bekannt.","hinweise":["Nach dem Einbürsten das Gel ausspucken und nicht schlucken.","Kinder bis 8 Jahre nur unter Aufsicht Erwachsener anwenden lassen.","Das Gel ersetzt die tägliche Zahnpflege mit fluoridhaltiger Zahnpasta nicht."],"darreichung":["Dentalgel (Gelée)"]},"olanzapin":{"wirkmechanismus":"Dämpft Wahn, Halluzinationen und manische Erregung, indem es im Gehirn die Wirkung der Botenstoffe Dopamin und Serotonin hemmt. Olanzapin blockiert Serotonin-5-HT2A- und Dopamin-D2-Rezeptoren sowie Histamin-H1-, Muskarin- und Alpha-1-Rezeptoren. Die H1-Blockade erklärt Müdigkeit und Gewichtszunahme, die Muskarinblockade Mundtrockenheit und Verstopfung. Abgebaut wird es v. a. über CYP1A2 und Glucuronidierung.","nebenwirkungen":{"sehrHaeufig":["Gewichtszunahme","Schläfrigkeit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Erhöhtes Prolaktin"],"haeufig":["Erhöhter Blutzucker, erhöhtes Cholesterin und Triglyceride, gesteigerter Appetit","Schwindel, Sitzunruhe (Akathisie), Parkinsonismus, Dyskinesien","Mundtrockenheit, Verstopfung","Vorübergehend erhöhte Leberwerte","Leukopenie, Neutropenie, Eosinophilie","Ödeme, Schwäche, Fieber","Gelenkschmerzen, Hautausschlag","Erektionsstörung, verminderte Libido"],"gelegentlich":["Neu auftretender oder verschlechterter Diabetes, selten mit Ketoazidose oder Koma","Krampfanfälle","Spätdyskinesien, Dystonie","Bradykardie, QT-Verlängerung","Venöse Thromboembolie (Thrombose, Lungenembolie)","Lichtempfindlichkeit, Haarausfall","Harnverhalt, Harninkontinenz","Milchfluss, Brustvergrösserung, Ausbleiben der Regel"],"selten":["Malignes neuroleptisches Syndrom","Kammerrhythmusstörungen, plötzlicher Herztod","Pankreatitis, Hepatitis","Thrombozytopenie","Rhabdomyolyse (Muskelzerfall)","Priapismus","Zypadhera: Post-Injektions-Syndrom mit starker Sedierung oder Delir"],"unbekannt":["DRESS (schwere Arzneimittelreaktion mit Hautausschlag, Eosinophilie und Organbeteiligung)","Entzugssymptome und Bewegungsstörungen beim Neugeborenen"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das Risiko überwiegt. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Olanzapin geht in die Muttermilch über. Nicht stillen.","hinweise":["Gewicht, Blutzucker und Blutfette vor und regelmässig während der Behandlung kontrollieren.","Zypadhera: nach jeder Injektion mindestens 3 Stunden in der Praxis bzw. Klinik bleiben und an diesem Tag nicht Auto fahren.","Rauchbeginn oder Rauchstopp ärztlich mitteilen (der Spiegel ändert sich).","Fahrtüchtigkeit kann beeinträchtigt sein; Alkohol meiden."],"darreichung":["Filmtabletten","Schmelztabletten","Depot-Injektionssuspension"]},"olaparib":{"wirkmechanismus":"Verhindert, dass Krebszellen Schäden an ihrem Erbgut reparieren. Olaparib hemmt die Enzyme PARP-1, -2 und -3, die Einzelstrangbrüche der DNA reparieren, und hält PARP an der DNA fest. Daraus entstehen Doppelstrangbrüche, die Zellen mit defekter homologer Rekombination (z. B. bei BRCA1/2-Mutation) nicht reparieren können – sie sterben ab (synthetische Letalität).","nebenwirkungen":{"sehrHaeufig":["Anämie (Blutarmut)","Neutropenie, Leukopenie, Thrombozytopenie","Übelkeit, Erbrechen, Durchfall, Dyspepsie (Verdauungsbeschwerden)","Müdigkeit und Schwäche","Appetitlosigkeit","Kopfschmerzen, Schwindel, Geschmacksstörungen","Husten, Atemnot"],"haeufig":["Stomatitis (Mundschleimhautentzündung)","Oberbauchschmerzen","Hautausschlag","Anstieg des Kreatinins im Blut","Venöse Thromboembolie","Lymphopenie"],"gelegentlich":["Myelodysplastisches Syndrom / akute myeloische Leukämie","Pneumonitis (Lungenentzündung)","Überempfindlichkeitsreaktionen, Dermatitis"],"selten":["Erythema nodosum (schmerzhafte Hautknoten)","Angioödem (Schwellung von Haut und Schleimhaut)"],"unbekannt":["Arzneimittelbedingte Leberschädigung"]},"schwangerschaft":"Nicht anwenden (fruchtschädigend im Tierversuch). Frauen sollen während und bis 6 Monate, Männer mit Partnerin bis 3 Monate nach der letzten Dosis sicher verhüten.","stillzeit":"Kontraindiziert während der Behandlung und 1 Monat danach.","hinweise":["Tabletten ganz schlucken, mit oder ohne Essen; Grapefruit und Grapefruitsaft meiden.","Blutbildkontrollen einhalten; anhaltende Müdigkeit, Fieber, blaue Flecken oder Blutungen melden.","Neue Medikamente, auch pflanzliche (Johanniskraut), immer zuerst mit Ärztin, Arzt oder Apotheke besprechen."],"darreichung":["Filmtabletten"]},"olipudase-alfa":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, das in den Zellen bestimmte Fettstoffe abbaut. Olipudase alfa ist eine gentechnisch hergestellte menschliche saure Sphingomyelinase, die in den Lysosomen Sphingomyelin zu Ceramid und Phosphocholin spaltet. Dadurch nehmen die Fettablagerungen in Leber, Milz und Lunge ab, die Organvergrösserung bildet sich zurück und die Lungenfunktion verbessert sich. Das Enzym überwindet die Blut-Hirn-Schranke nicht und wirkt deshalb nicht auf die Beteiligung des Nervensystems.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Fieber","Urtikaria (Nesselsucht) und Juckreiz","Übelkeit, Erbrechen","Bauchschmerzen","Myalgie (Muskelschmerzen)"],"haeufig":["Anaphylaxie (schwere allergische Reaktion)","Andere Überempfindlichkeitsreaktionen","Hautausschlag, Hautrötung","Gelenk- und Rückenschmerzen","Erhöhte Leberwerte (Transaminasen)","Müdigkeit, Schüttelfrost"]},"schwangerschaft":"Nicht empfohlen, ausser der Gesundheitszustand der Frau erfordert die Behandlung; im Tierversuch traten Fehlbildungen auf. Frauen im gebärfähigen Alter verhüten während der Behandlung und bis 14 Tage nach der letzten Dosis.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Die Infusion erfolgt alle 2 Wochen durch Fachpersonen; die Dosis wird zu Beginn über mehrere Wochen schrittweise gesteigert, um Reaktionen zu vermeiden.","Leberwerte werden vor Beginn und während der Dosissteigerung kontrolliert.","Fieber, Ausschlag, Atemnot oder Schwindel während oder nach der Infusion sofort melden."],"darreichung":["Pulver zur Herstellung eines Infusionskonzentrats"]},"olmesartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II blockiert. Olmesartanmedoxomil ist ein Prodrug, das bei der Aufnahme aus dem Darm rasch zum Wirkstoff Olmesartan gespalten wird. Olmesartan blockiert selektiv den Angiotensin-II-Rezeptor Typ 1 (AT1): Die Gefässe erweitern sich, die Aldosteronausschüttung sowie die Salz- und Wasserrückhaltung nehmen ab. Der Abbau von Bradykinin wird nicht gehemmt, daher ist Reizhusten seltener als bei ACE-Hemmern. Olmesartan wird nicht über Cytochrom-P450-Enzyme abgebaut.","nebenwirkungen":{"haeufig":["Schwindel, Kopfschmerzen","Bronchitis, Husten, Rachen- und Nasenschleimhautentzündung","Durchfall, Bauchschmerzen, Übelkeit, Verdauungsbeschwerden, Magen-Darm-Entzündung","Rücken-, Knochen- und Gelenkbeschwerden","Harnwegsinfekt, Hämaturie (Blut im Urin)","Periphere Ödeme (Wassereinlagerungen), Müdigkeit, Brustschmerzen, grippeähnliche Beschwerden","Erhöhte Leberwerte, Harnstoff, CK (Muskelenzym), Triglyceride und Harnsäure"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Anaphylaktische (schwere allergische) Reaktionen","Vertigo (Drehschwindel)","Angina pectoris (Brustenge)","Erbrechen","Hautausschlag, Juckreiz, Nesselsucht, allergische Dermatitis","Muskelschmerzen","Gesichtsödem, Schwäche, Unwohlsein"],"selten":["Hyperkaliämie (erhöhtes Kalium)","Hypotonie (tiefer Blutdruck)","Akutes Nierenversagen, Niereninsuffizienz, erhöhtes Kreatinin","Angioödem (Schwellung von Gesicht, Zunge oder Rachen)","Muskelkrämpfe","Lethargie (Benommenheit, Antriebslosigkeit)"],"sehrSelten":["Sprue-ähnliche Enteropathie (schwerer chronischer Durchfall mit Gewichtsverlust)"],"unbekannt":["Autoimmunhepatitis (Leberentzündung)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schäden an Nieren und Schädelknochen des Ungeborenen, Fruchtwassermangel). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch auf ein geeignetes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten fehlen; besser untersuchte Alternativen wählen, besonders bei Neu- und Frühgeborenen.","hinweise":["Einmal täglich, mit oder ohne Essen, möglichst zur gleichen Tageszeit.","Anhaltenden, starken Durchfall mit Gewichtsverlust ärztlich melden (seltene Sprue-ähnliche Darmerkrankung).","Kalium und Nierenwerte zu Beginn und regelmässig kontrollieren lassen.","Zu Beginn können Schwindel und Müdigkeit die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"olodaterol":{"wirkmechanismus":"Erweitert die Atemwege über 24 Stunden, indem es die Bronchialmuskulatur entspannt. Olodaterol bindet mit hoher Affinität und Selektivität an Beta-2-Adrenozeptoren und wirkt dort als nahezu voller Agonist; der Anstieg von cAMP führt zur Relaxation der glatten Muskulatur. Die lange Wirkdauer beruht auf der langsamen Ablösung vom Rezeptor, deshalb genügt eine Anwendung pro Tag.","nebenwirkungen":{"gelegentlich":["Nasopharyngitis (Erkältungssymptome)","Schwindel"],"selten":["Bluthochdruck","Hautausschlag","Gelenkschmerzen (Arthralgie)"],"unbekannt":["Herzrasen (Tachykardie), Herzklopfen, Herzrhythmusstörungen","Myokardischämie (Durchblutungsstörung des Herzmuskels), Angina pectoris","Zittern, Kopfschmerzen, Nervosität, Schlaflosigkeit","Mundtrockenheit, Übelkeit","Muskelkrämpfe","Hypokaliämie (Kaliummangel), Hyperglykämie (erhöhter Blutzucker)","Paradoxer Bronchospasmus"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; vorsichtshalber nur anwenden, wenn der Nutzen das Risiko klar überwiegt. Beta-2-Sympathomimetika können die Wehen hemmen.","stillzeit":"Nicht bekannt, ob Olodaterol beim Menschen in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich zur gleichen Tageszeit inhalieren; vor dem ersten Gebrauch die Patrone einsetzen und den Respimat nach Anleitung vorbereiten.","Nicht für akute Atemnot – dafür ein rasch wirksames Bedarfsspray bereithalten.","Inhalationstechnik regelmässig in der Apotheke oder Praxis überprüfen lassen."],"darreichung":["Lösung zur Inhalation (Respimat-Inhalator)"]},"olopatadin":{"wirkmechanismus":"Lindert allergische Augenbeschwerden wie Juckreiz und Rötung. Olopatadin blockiert selektiv den Histamin-H1-Rezeptor und hemmt zusätzlich die Freisetzung entzündungsfördernder Botenstoffe aus den Mastzellen der Bindehaut. An Alpha-Adrenozeptoren, Dopamin-, Muskarin- und Serotoninrezeptoren wirkt es praktisch nicht. Nach dem Eintropfen gelangt nur sehr wenig Wirkstoff in den Körper.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Geschmacksstörung","Augenschmerzen, Augenreizung","Trockenes Auge, ungewöhnliches Gefühl im Auge","Trockene Nase","Müdigkeit"],"gelegentlich":["Schwindel, vermindertes Berührungsempfinden (Hypästhesie)","Hornhautschäden (Erosion, punktförmige Keratitis)","Verschwommenes Sehen, Lichtscheu, Augenjucken","Augenrötung, Lidschwellung, vermehrter Tränenfluss","Schnupfen (Rhinitis)","Kontaktdermatitis, trockene Haut"],"unbekannt":["Überempfindlichkeitsreaktionen, Gesichtsschwellung","Schläfrigkeit","Atemnot, Nasennebenhöhlenentzündung","Übelkeit, Erbrechen","Hautrötung"]},"schwangerschaft":"Nicht empfohlen in der Schwangerschaft und bei Frauen im gebärfähigen Alter ohne Verhütung.","stillzeit":"Im Tierversuch geht Olopatadin in die Milch über; ein Risiko für den Säugling ist nicht auszuschliessen – Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen.","Nach dem Eintropfen kann das Sehen kurz verschwommen sein – erst danach Auto fahren.","Andere Augentropfen mit mindestens 5 Minuten Abstand anwenden.","Tropferspitze nicht mit Auge oder Fingern berühren, um Verunreinigungen zu vermeiden."],"darreichung":["Augentropfen"]},"omalizumab":{"wirkmechanismus":"Fängt den Allergie-Antikörper IgE im Blut ab und dämpft so allergische Reaktionen. Omalizumab ist ein humanisierter monoklonaler Antikörper, der an freies Immunglobulin E bindet und dessen Andocken an den hochaffinen IgE-Rezeptor (FcεRI) auf Mastzellen und basophilen Granulozyten verhindert. Dadurch sinkt das freie IgE, die Zahl der Rezeptoren auf diesen Zellen nimmt ab und die Freisetzung von Entzündungsstoffen wie Histamin wird gebremst. Die volle Wirkung zeigt sich bei Asthma nach etwa 12–16 Wochen.","nebenwirkungen":{"sehrHaeufig":["Fieber (bei Kindern von 6 bis 12 Jahren)"],"haeufig":["Kopfschmerzen (bei Kindern sehr häufig)","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Juckreiz, Schwellung)","Oberbauchschmerzen (bei Kindern)","Gelenkschmerzen","Schwindel","Nasennebenhöhlenentzündung, Infekte der oberen Atemwege (bei Urtikaria)"],"gelegentlich":["Rachenentzündung","Schläfrigkeit, Kribbeln (Parästhesien), Ohnmacht","Blutdruckabfall beim Aufstehen, Hitzewallungen (Flush)","Allergischer Bronchospasmus, Husten","Übelkeit, Durchfall, Verdauungsbeschwerden","Nesselsucht, Ausschlag, Juckreiz, Lichtempfindlichkeit","Müdigkeit, grippeähnliche Beschwerden, Armschwellung, Gewichtszunahme"],"selten":["Anaphylaxie (schwere allergische Reaktion), auch verzögert","Angioödem, Kehlkopfschwellung","Parasiteninfektionen (Wurmbefall)","Bildung von Antikörpern gegen Omalizumab"],"unbekannt":["Serumkrankheit (Fieber, Gelenkschmerzen, Lymphknotenschwellung, Ausschlag)","Eosinophile Granulomatose mit Polyangiitis (Churg-Strauss-Syndrom)","Schwere Thrombozytopenie (Mangel an Blutplättchen)","Haarausfall","Muskelschmerzen, Gelenkschwellung"]},"schwangerschaft":"Daten aus einem Schwangerschaftsregister zeigen kein erhöhtes Fehlbildungsrisiko; Anwendung nur, wenn klinisch notwendig.","stillzeit":"IgG-Antikörper gehen in geringen Mengen in die Muttermilch über; die Daten zeigen kein Risiko für gestillte Kinder. Anwendung bei klinischer Notwendigkeit möglich.","hinweise":["Wird alle 2 oder 4 Wochen unter die Haut gespritzt; die Dosis richtet sich nach IgE-Wert und Körpergewicht.","Die ersten Injektionen erfolgen unter ärztlicher Aufsicht; bei Atemnot, Schwellung von Gesicht oder Zunge, Schwindel oder Kollaps sofort den Notruf (144) wählen.","Bisherige Asthma-Medikamente, insbesondere Kortison, nicht eigenmächtig absetzen.","Vor Reisen in Gebiete mit häufigen Wurminfektionen ärztlich beraten lassen."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen) zur Anwendung unter die Haut"]},"omaveloxolon":{"wirkmechanismus":"Stärkt die körpereigene Abwehr der Zellen gegen oxidativen Stress, der bei der Friedreich-Ataxie Nerven- und Muskelzellen schädigt. Omaveloxolon aktiviert den Transkriptionsfaktor Nrf2, der bei dieser Erkrankung vermindert aktiv ist. Nrf2 schaltet Gene für antioxidative und entzündungshemmende Schutzproteine an und verbessert die Funktion der Mitochondrien. Der genaue Wirkmechanismus beim Menschen ist nicht vollständig geklärt.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (ALT, AST)","Kopfschmerzen","Übelkeit","Bauchschmerzen","Müdigkeit","Durchfall","Verminderter Appetit, Gewichtsabnahme","Muskelkrämpfe"],"unbekannt":["Anstieg des Herzmarkers BNP","Anstieg des LDL-Cholesterins"]},"schwangerschaft":"Nicht empfohlen. Frauen im gebärfähigen Alter müssen zuverlässig verhüten; hormonale Methoden allein genügen nicht.","stillzeit":"Ein Risiko für das gestillte Kind kann nicht ausgeschlossen werden; nur nach ärztlicher Abwägung.","hinweise":["Auf nüchternen Magen einnehmen (mindestens 1 Stunde vor dem Essen); Kapseln ganz schlucken.","Grapefruit und Grapefruitsaft meiden.","Regelmässige Kontrollen von Leberwerten, BNP und Blutfetten."],"darreichung":["Hartkapseln"]},"omega-3-saeurenethylester":{"wirkmechanismus":"Senkt die Triglyceride, indem die Leber weniger Fett zu Blutfetten verarbeitet. Die Omega-3-Fettsäuren Eicosapentaensäure (EPA) und Docosahexaensäure (DHA) hemmen in der Leber die Veresterung von Fettsäuren und die Bildung von Triglyceriden und steigern den Fettsäureabbau (Beta-Oxidation). Dadurch wird weniger VLDL gebildet und ins Blut abgegeben. Das LDL-Cholesterin kann dabei leicht ansteigen.","nebenwirkungen":{"haeufig":["Dyspepsie (Verdauungsbeschwerden), Übelkeit","Bauchschmerzen und andere Magen-Darm-Beschwerden (Aufstossen, Blähungen, Durchfall, Verstopfung)","Vorhofflimmern"],"gelegentlich":["Überempfindlichkeitsreaktionen","Schwindel, Kopfschmerzen, Geschmacksstörung","Hypotonie (tiefer Blutdruck)","Nasenbluten","Magen-Darm-Blutung","Hautausschlag","Erhöhter Blutzucker, Gicht"],"selten":["Leberfunktionsstörungen, erhöhte Leberwerte","Nesselsucht (Urtikaria)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn es ärztlich eindeutig notwendig ist.","stillzeit":"Übergang in die Muttermilch und Auswirkungen auf das Kind sind nicht bekannt – nur nach ärztlicher Abwägung.","hinweise":["Kapseln mit einer Mahlzeit einnehmen; das verbessert die Verträglichkeit.","Ersetzt fettarme Ernährung, Gewichtsabnahme und Alkoholverzicht nicht.","Herzstolpern oder unregelmässigen Puls ärztlich melden; unter Blutverdünnern INR-Kontrollen wahrnehmen."],"darreichung":["Weichkapseln"]},"omeprazol":{"wirkmechanismus":"Senkt die Bildung von Magensäure stark und anhaltend. Omeprazol ist eine Vorstufe (Prodrug), die sich in den sauren Belegzellen der Magenschleimhaut anreichert und dort in die aktive Form (ein Sulfenamid) umgewandelt wird. Diese blockiert irreversibel die Protonenpumpe (H+/K+-ATPase), den letzten Schritt der Säurebildung – unabhängig vom auslösenden Reiz. Die Wirkung hält länger an, als der Wirkstoff im Blut nachweisbar ist, weil erst neue Pumpen gebildet werden müssen. Omeprazol wird über CYP2C19 und CYP3A4 abgebaut und hemmt selbst CYP2C19.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Blähungen","Durchfall oder Verstopfung","Übelkeit, Erbrechen","Gutartige Drüsenpolypen im Magen (Fundusdrüsenpolypen)"],"gelegentlich":["Schlafstörungen","Schwindel, Kribbeln (Parästhesien), Schläfrigkeit","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht","Knochenbrüche (Hüfte, Handgelenk, Wirbelsäule)","Unwohlsein, Wassereinlagerungen in den Beinen"],"selten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Überempfindlichkeitsreaktionen wie Fieber, Angioödem oder Anaphylaxie","Hyponatriämie (Natriummangel)","Verwirrtheit, Unruhe, Depression","Geschmacksstörungen, verschwommenes Sehen, Mundtrockenheit","Bronchospasmus (Verkrampfung der Atemwege)","Hepatitis, Mundschleimhautentzündung, Pilzbefall im Magen-Darm-Trakt","Interstitielle Nephritis (Nierenentzündung); Lichtempfindlichkeit, Haarausfall, Gelenk- und Muskelschmerzen"],"sehrSelten":["Agranulozytose, Panzytopenie (schwerer Mangel an Blutzellen)","Leberversagen, hepatische Enzephalopathie","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Halluzinationen, Aggressivität","Muskelschwäche, Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Hypomagnesiämie (Magnesiummangel), dadurch auch Calcium- und Kaliummangel","Mikroskopische Kolitis (Dickdarmentzündung mit wässrigem Durchfall)","Subakuter kutaner Lupus erythematodes","DRESS (schwere Arzneimittelreaktion mit Ausschlag, Fieber und Organbeteiligung)"]},"schwangerschaft":"Kann in der Schwangerschaft angewendet werden; umfangreiche Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Geht in geringer Menge in die Muttermilch über; in üblicher Dosis ist eine Schädigung des Säuglings unwahrscheinlich – Anwendung nach ärztlicher Rücksprache möglich.","hinweise":["Morgens vor dem Frühstück einnehmen; Kapseln und Tabletten ganz schlucken, nicht zerkauen. MUPS-Tabletten dürfen in Wasser zerfallen gelassen werden.","Selbstbehandlung von Sodbrennen ohne ärztlichen Rat höchstens 14 Tage.","Nach längerer Einnahme nicht abrupt absetzen: vorübergehend vermehrte Säurebildung (Rebound) möglich – Absetzen ärztlich begleiten.","Bei Langzeitbehandlung regelmässig die Notwendigkeit sowie Magnesium und Vitamin B12 überprüfen lassen."],"darreichung":["Magensaftresistente Tabletten (MUPS, in Wasser zerfallend)","Magensaftresistente Kapseln"]},"onasemnogen-abeparvovec":{"wirkmechanismus":"Bringt eine funktionsfähige Kopie des fehlenden Gens in die Nervenzellen. Onasemnogen-Abeparvovec ist ein nicht vermehrungsfähiges adenoassoziiertes Virus vom Serotyp 9 (AAV9), das ein intaktes menschliches SMN1-Gen enthält. Nach einer einzigen Infusion gelangt der Vektor unter anderem in die Motoneuronen des Rückenmarks; das Gen verbleibt grösstenteils ausserhalb der Chromosomen (episomal) und wird dauerhaft abgelesen. Das gebildete SMN-Protein verhindert das weitere Absterben der Motoneuronen.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (Transaminasen)"],"haeufig":["Erbrechen","Fieber","Thrombozytopenie (Mangel an Blutplättchen)","Erhöhtes Troponin (Herzmuskelwert)"],"unbekannt":["Akute Leberschädigung und akutes Leberversagen","Thrombotische Mikroangiopathie mit Nierenversagen"]},"schwangerschaft":"Für Säuglinge und Kleinkinder bestimmt; keine Daten zur Anwendung in der Schwangerschaft.","stillzeit":"Für Säuglinge und Kleinkinder bestimmt; keine Daten zur Anwendung in der Stillzeit.","hinweise":["Wird einmalig im Spital als Infusion gegeben; begleitend erhält das Kind ab dem Vortag während mindestens eines Monats Kortison (Prednisolon), das danach langsam ausgeschlichen wird.","Bei Gelbfärbung von Haut oder Augen, dunklem Urin, Teilnahmslosigkeit, Blutungen, Blutergüssen oder weniger Urin sofort ärztliche Hilfe holen.","Leberwerte, Blutbild, Nierenwerte und Troponin werden nach der Infusion regelmässig kontrolliert.","Während etwa eines Monats nach der Infusion nach dem Wickeln gründlich die Hände waschen (vorübergehende Ausscheidung des Vektors im Stuhl)."],"darreichung":["Infusionssuspension (einmalige intravenöse Gabe)"]},"ondansetron":{"wirkmechanismus":"Unterdrückt den Brechreiz, der durch Chemotherapie, Bestrahlung oder Narkose ausgelöst wird. Diese Behandlungen setzen im Dünndarm Serotonin frei, das über 5-HT3-Rezeptoren an Nervenendigungen des Vagusnervs und in der Brechreizzone des Hirnstamms Erbrechen auslöst. Ondansetron blockiert diese 5-HT3-Rezeptoren selektiv, peripher und zentral. Es wird in der Leber über mehrere Enzyme (vor allem CYP3A4, daneben CYP1A2 und CYP2D6) abgebaut.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Wärmegefühl, Hautrötung (Flush)","Obstipation (Verstopfung)","Reaktionen an der Injektionsstelle"],"gelegentlich":["Krampfanfälle","Bewegungsstörungen (z. B. Blickkrämpfe, Dystonie)","Herzrhythmusstörungen, Brustschmerzen, Bradykardie (langsamer Puls)","Hypotonie (tiefer Blutdruck)","Schluckauf","Erhöhte Leberwerte"],"selten":["Anaphylaxie und andere sofortige Überempfindlichkeitsreaktionen","QT-Verlängerung, Torsade de pointes","Vorübergehende Sehstörungen (verschwommenes Sehen), Schwindel bei rascher Injektion"],"sehrSelten":["Vorübergehende Blindheit, meist bei Injektion","Schwere Hautreaktionen (toxische epidermale Nekrolyse)"],"unbekannt":["Myokardischämie (Durchblutungsstörung des Herzmuskels)"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel nicht anwenden: Daten weisen auf ein leicht erhöhtes Risiko für Lippen-Kiefer-Gaumenspalten hin. Später nur nach ärztlicher Abwägung; Frauen im gebärfähigen Alter sollen eine Verhütung in Betracht ziehen.","stillzeit":"Ondansetron geht bei Tieren in die Milch über; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Schmelztabletten auf die Zunge legen und zergehen lassen, ohne Wasser.","Verstopfung ist häufig: ausreichend trinken; bei anhaltender Verstopfung ärztlichen Rat einholen.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Schmelztabletten","Lösung zum Einnehmen","Injektionslösung"]},"opicapon":{"wirkmechanismus":"Verlängert die Wirkung von Levodopa, indem es dessen Abbau im Körper bremst. Opicapon hemmt ausserhalb des Gehirns die Catechol-O-Methyltransferase (COMT), die Levodopa zu 3-O-Methyldopa abbaut. Dadurch bleibt der Levodopa-Spiegel im Blut höher und gleichmässiger, und mehr Levodopa erreicht das Gehirn. Opicapon bindet sehr fest an das Enzym: Obwohl es selbst nur kurz im Blut bleibt, hält die Hemmung über 24 Stunden an, deshalb genügt eine Einnahme pro Tag.","nebenwirkungen":{"sehrHaeufig":["Dyskinesien (unwillkürliche Überbewegungen)"],"haeufig":["Abnorme Träume, Halluzinationen, Schlaflosigkeit","Schwindel, Kopfschmerzen, Schläfrigkeit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Verstopfung, Mundtrockenheit, Erbrechen","Muskelkrämpfe","Erhöhte Kreatinkinase (Muskelenzym) im Blut"],"gelegentlich":["Verminderter Appetit, Gewichtsabnahme","Angst, Depression, Albträume","Synkope (Ohnmacht)","Herzklopfen, Blutdruckanstieg","Atemnot","Bauchschmerzen, Blähbauch, Verdauungsbeschwerden","Dunkel verfärbter Urin"],"unbekannt":["Impulskontrollstörungen (z. B. Spielsucht, Kaufsucht)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; während der Schwangerschaft und bei Frauen im gebärfähigen Alter ohne sichere Verhütung nicht empfohlen.","stillzeit":"Ging im Tierversuch in die Milch über; während der Behandlung nicht stillen.","hinweise":["Einmal täglich vor dem Schlafengehen einnehmen, mindestens 1 Stunde vor oder nach einer Levodopa-Dosis.","Zu Beginn nehmen Überbewegungen oft zu – dann die Levodopa-Dosis ärztlich anpassen lassen.","Schläfrigkeit und plötzliches Einschlafen sind möglich – in diesem Fall nicht Auto fahren."],"darreichung":["Hartkapseln"]},"opipramol":{"wirkmechanismus":"Wirkt angstlösend, beruhigend und leicht stimmungsaufhellend. Anders als klassische trizyklische Antidepressiva hemmt Opipramol die Wiederaufnahme von Serotonin und Noradrenalin kaum; es bindet vor allem an Sigma-Rezeptoren im Gehirn. Zusätzlich blockiert es Histamin-H1-Rezeptoren (dämpfend) sowie in geringerem Mass Dopamin-D2-, Serotonin-5-HT2-, Muskarin- und Alpha-1-Rezeptoren. Abbau in der Leber unter Beteiligung von CYP2D6.","nebenwirkungen":{"haeufig":["Müdigkeit, besonders zu Behandlungsbeginn","Mundtrockenheit","Verstopfte Nase","Blutdruckabfall und Schwindel beim Aufstehen (orthostatische Dysregulation)"],"gelegentlich":["Benommenheit","Zittern (Tremor)","Verschwommenes Sehen (Akkommodationsstörungen)","Blasenentleerungsstörungen","Obstipation (Verstopfung)","Gewichtszunahme","Herzrasen, Herzklopfen","Hautausschlag, Juckreiz"],"selten":["Unruhe, Erregungszustände","Kopfschmerzen, Missempfindungen (Parästhesien)","Harnverhalt","Wassereinlagerungen (Ödeme)","Verwirrtheit, Delir (v. a. bei älteren Menschen)","Krampfanfälle","Störungen der Erregungsleitung im Herzen","Leukopenie (Mangel an weissen Blutkörperchen)"],"sehrSelten":["Agranulozytose (starker Mangel an weissen Blutkörperchen)","Schwere Leberfunktionsstörungen, Gelbsucht","Glaukomanfall","Haarausfall"]},"schwangerschaft":"Im 1. Drittel nicht anwenden; danach nur nach strenger ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über – während der Behandlung nicht stillen.","hinweise":["Kann besonders zu Beginn müde machen: Vorsicht beim Autofahren, keinen Alkohol trinken.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung.","Bei Fieber, Halsschmerzen oder Entzündungen im Mund ärztlich das Blutbild kontrollieren lassen."],"darreichung":["Dragées"]},"orale-rehydratationssalze-glucose-elektrolyt":{"wirkmechanismus":"Ersetzt die beim Durchfall verlorene Flüssigkeit und die Salze und beugt so dem Austrocknen vor. Glucose und Natrium werden im Dünndarm gemeinsam über einen Transporter (SGLT1) aufgenommen, und Wasser folgt passiv nach; dieser Transportweg funktioniert auch bei infektiösem Durchfall weiter. Kalium ersetzt Kaliumverluste, Citrat gleicht eine durch den Durchfall entstandene Übersäuerung (metabolische Azidose) aus. Die Lösung verkürzt den Durchfall nicht, verhindert aber gefährlichen Flüssigkeitsmangel.","nebenwirkungen":{"unbekannt":["Erbrechen, besonders bei zu raschem Trinken","Hypernatriämie (zu viel Natrium) bei falscher, zu konzentrierter Zubereitung","Hyperkaliämie (zu viel Kalium) bei eingeschränkter Nierenfunktion"]},"schwangerschaft":"Anwendung in der Schwangerschaft möglich.","stillzeit":"Anwendung in der Stillzeit möglich; gestillte Säuglinge mit Durchfall weiter stillen.","hinweise":["Pulver genau in der angegebenen Menge Trinkwasser auflösen (für Säuglinge abgekochtes, abgekühltes Wasser); nicht mit Milch, Saft oder Süssgetränken mischen und nicht zusätzlich zuckern.","In kleinen Schlucken trinken; bei Erbrechen löffelweise alle paar Minuten geben.","Zubereitete Lösung im Kühlschrank aufbewahren und nach 24 Stunden verwerfen.","Nach dem Ausgleich des Flüssigkeitsverlusts normal weiter essen; Säuglinge weiter stillen bzw. füttern."],"darreichung":["Pulver zur Herstellung einer Lösung zum Einnehmen (Beutel)"]},"orlistat":{"wirkmechanismus":"Verhindert, dass ein Teil des Nahrungsfetts verdaut und aufgenommen wird. Orlistat bindet im Magen und Dünndarm fest an die fettspaltenden Enzyme (Lipasen) von Magen und Bauchspeicheldrüse und macht sie unwirksam. Die Nahrungsfette (Triglyceride) können so nicht in aufnehmbare Bausteine zerlegt werden; rund 30 % des Fetts werden mit dem Stuhl ausgeschieden, die Kalorienaufnahme sinkt. Orlistat selbst wird kaum ins Blut aufgenommen.","nebenwirkungen":{"sehrHaeufig":["Öliger Ausfluss aus dem After (Fettflecken in der Wäsche)","Blähungen mit Stuhlabgang, Stuhldrang","Fettiger, öliger oder weicher Stuhl","Bauchschmerzen","Kopfschmerzen","Infekte der oberen Atemwege, Grippe","Hypoglykämie (Unterzuckerung) bei Typ-2-Diabetes"],"haeufig":["Schmerzen oder Beschwerden im Enddarm","Flüssiger Stuhl, Stuhlinkontinenz","Blähbauch","Zahn- und Zahnfleischbeschwerden","Infekte der unteren Atemwege, Harnwegsinfekte","Angst, Müdigkeit","Menstruationsstörungen"],"unbekannt":["Blutungen aus dem Enddarm","Divertikulitis, Pankreatitis (Bauchspeicheldrüsenentzündung), Gallensteine","Hepatitis, teils schwer; erhöhte Leberwerte","Oxalat-Nierenschädigung bis Nierenversagen","Bullöse (blasenbildende) Hautausschläge","Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem, Bronchospasmus","Erniedrigter Quick-Wert bzw. erhöhter INR"]},"schwangerschaft":"In der Schwangerschaft nicht empfohlen.","stillzeit":"Kontraindiziert, da nicht bekannt ist, ob Orlistat in die Muttermilch übergeht.","hinweise":["Zu jeder Hauptmahlzeit (während oder bis 1 Stunde danach) einnehmen; fällt eine Mahlzeit aus oder ist sie fettfrei, die Kapsel weglassen.","Ausgewogen und fettarm essen (etwa 30 % der Kalorien aus Fett) – fettreiche Mahlzeiten verstärken die Magen-Darm-Beschwerden.","Ein Multivitaminpräparat mit fettlöslichen Vitaminen am besten vor dem Schlafengehen einnehmen.","Ärztliche Kontrolle nach 12 Wochen: ohne Gewichtsabnahme von mindestens 5 % die Behandlung beenden."],"darreichung":["Kapseln"]},"ornithinaspartat":{"wirkmechanismus":"Hilft dem Körper, das giftige Ammoniak abzubauen, das sich bei einer geschwächten Leber im Blut anreichert. Ornithin und Aspartat sind Aminosäuren, die als Bausteine und Aktivatoren der Ammoniakentgiftung dienen: Ornithin fördert in den Leberzellen den Harnstoffzyklus, über den Ammoniak als Harnstoff ausgeschieden wird. Zudem entsteht aus beiden Aminosäuren Glutamat, das Ammoniak in Leber, Muskulatur und Gehirn als Glutamin bindet. So sinkt der Ammoniakspiegel im Blut.","nebenwirkungen":{"gelegentlich":["Übelkeit","Erbrechen","Magen- oder Bauchschmerzen","Blähungen","Durchfall"],"sehrSelten":["Gliederschmerzen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Aus Vorsicht nicht anwenden, ausser die Ärztin oder der Arzt hält es nach sorgfältiger Abwägung für unbedingt nötig.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; Anwendung in der Stillzeit vermeiden.","hinweise":["Granulat in einem Glas Flüssigkeit (z. B. Wasser, Tee oder Saft) auflösen und zu oder nach den Mahlzeiten einnehmen.","Die Infusion wird verdünnt und langsam unter ärztlicher Überwachung verabreicht."],"darreichung":["Granulat (Beutel)","Infusionskonzentrat"]},"oseltamivir":{"wirkmechanismus":"Verhindert, dass sich Grippeviren im Körper weiter ausbreiten. Oseltamivir ist eine Vorstufe (Prodrug), die in der Leber durch Esterasen zu Oseltamivircarboxylat umgewandelt wird. Dieses hemmt selektiv die Neuraminidase der Influenza-A- und -B-Viren, ein Enzym an der Virusoberfläche, das die Freisetzung neu gebildeter Viren aus infizierten Zellen ermöglicht. Die Viren bleiben an der Zelloberfläche haften und können sich nicht ausbreiten; gegen Erkältungsviren wirkt Oseltamivir nicht.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Erbrechen (vor allem bei Kindern)"],"haeufig":["Bauchschmerzen, Verdauungsbeschwerden, Durchfall","Schwindel, Müdigkeit, Schlaflosigkeit","Husten, Halsschmerzen, Schnupfen","Bronchitis, Infekte der oberen Atemwege, Herpes simplex","Schmerzen, Gliederschmerzen, Fieber","Bindehautentzündung, Ohrenschmerzen (bei Kindern)"],"gelegentlich":["Krampfanfälle, Bewusstseinsstörungen","Herzrhythmusstörungen","Erhöhte Leberwerte","Hautausschlag, Ekzem, Nesselsucht","Überempfindlichkeitsreaktionen"],"selten":["Neuropsychiatrische Störungen wie Verwirrtheit, Delir, Halluzinationen, Albträume, Angst, abnormes Verhalten bis zur Selbstverletzung (vor allem bei Kindern und Jugendlichen)","Thrombozytopenie (Mangel an Blutplättchen)","Sehstörungen","Magen-Darm-Blutungen, blutige Darmentzündung","Hepatitis bis zum Leberversagen","Anaphylaxie und Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)"]},"schwangerschaft":"Kann in der Schwangerschaft nach ärztlicher Abwägung angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko, und Schwangere haben ein erhöhtes Risiko für schwere Grippeverläufe.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; die Anwendung in der Stillzeit ist nach ärztlicher Abwägung möglich.","hinweise":["Möglichst früh beginnen, am besten innerhalb von 48 Stunden nach den ersten Grippesymptomen; Behandlung vollständig durchführen (meist 5 Tage).","Zusammen mit einer Mahlzeit eingenommen wird es oft besser vertragen.","Bei Kindern und Jugendlichen auf ungewöhnliches Verhalten achten.","Die jährliche Grippeimpfung bleibt der wichtigste Schutz."],"darreichung":["Kapseln","Pulver zur Herstellung einer Suspension zum Einnehmen"]},"osilodrostat":{"wirkmechanismus":"Senkt den krankhaft erhöhten Kortisolspiegel, indem es dessen Herstellung in der Nebennierenrinde bremst. Osilodrostat hemmt das Enzym 11-beta-Hydroxylase (CYP11B1), das den letzten Schritt der Kortisolbildung katalysiert, und in geringerem Mass die Aldosteronsynthase (CYP11B2). Weil sich dadurch Hormonvorstufen anstauen, können das Kalium sinken sowie Blutdruck und männliche Hormone ansteigen.","nebenwirkungen":{"sehrHaeufig":["Nebenniereninsuffizienz (Kortisolmangel)","Übelkeit, Erbrechen","Durchfall, Bauchschmerzen","Müdigkeit","Ödeme (Wassereinlagerungen)","Kopfschmerzen, Schwindel","Gelenkschmerzen","Appetitlosigkeit"],"haeufig":["QT-Verlängerung im EKG","Herzrasen (Tachykardie)","Ohnmacht (Synkope)","Akne und vermehrte Behaarung (Hirsutismus)","Hautausschlag","Erhöhte Leberwerte","Muskelschmerzen"],"unbekannt":["Kaliummangel (Hypokaliämie)","Bluthochdruck","Tiefer Blutdruck (Hypotonie), oft als Zeichen eines Kortisolmangels"]},"schwangerschaft":"Nicht empfohlen; Tierversuche zeigen schädliche Wirkungen. Frauen im gebärfähigen Alter sollen während und mindestens eine Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und mindestens eine Woche danach nicht stillen.","hinweise":["Zweimal täglich mit oder ohne Essen einnehmen; die Dosis wird anhand der Kortisolwerte schrittweise angepasst.","Bei Müdigkeit, Übelkeit, Erbrechen, Schwindel oder Schwäche sofort ärztlich melden (möglicher Kortisolmangel).","Regelmässige Kontrollen von Kortisol, Kalium, Magnesium, Leberwerten und EKG."],"darreichung":["Filmtabletten"]},"osimertinib":{"wirkmechanismus":"Blockiert gezielt das Wachstumssignal von Lungenkrebszellen mit veränderter EGFR-Erbinformation. Osimertinib bindet irreversibel an den mutierten epidermalen Wachstumsfaktor-Rezeptor (EGFR) mit den sensibilisierenden Mutationen Exon-19-Deletion und L858R sowie der Resistenzmutation T790M. Den normalen (Wildtyp-)EGFR hemmt es deutlich schwächer, was Haut- und Darmnebenwirkungen vermindert. Osimertinib gelangt auch ins Gehirn und wirkt gegen Hirnmetastasen.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Stomatitis (Mundschleimhautentzündung)","Hautausschlag, akneartige Hautveränderungen","Nagelbettentzündung (Paronychie)","Trockene Haut, Juckreiz","Appetitlosigkeit","Abnahme von weissen Blutkörperchen, Neutrophilen, Lymphozyten und Blutplättchen (Laborwerte)"],"haeufig":["Interstitielle Lungenerkrankung, Pneumonitis","Nasenbluten","Haarausfall, Nesselsucht","Hand-Fuss-Syndrom (palmar-plantare Erythrodysästhesie)","Abnahme der Herzpumpfunktion (LVEF)","Erhöhtes Kreatinin und erhöhte Kreatinkinase (CK)"],"gelegentlich":["QT-Verlängerung im EKG","Keratitis (Hornhautentzündung)","Erythema multiforme","Hautvaskulitis (Entzündung kleiner Hautgefässe)"],"selten":["Stevens-Johnson-Syndrom","Myositis (Muskelentzündung)"],"unbekannt":["Aplastische Anämie (Versagen der Blutbildung)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Indikation (im Tierversuch fruchtschädigend). Frauen müssen während und bis 2 Monate, Männer bis 4 Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich etwa zur gleichen Zeit, mit oder ohne Mahlzeit einnehmen; bei Schluckproblemen die Tablette in Wasser zerfallen lassen (nicht zerdrücken).","Neuer oder verstärkter Husten, Atemnot oder Fieber sofort melden (medikamentöse Lungenentzündung möglich).","EKG und Herzfunktion werden je nach Risiko kontrolliert; Johanniskraut ist nicht erlaubt.","Augenschmerzen, -rötung oder Sehstörungen sofort augenärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"oxaliplatin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen, sodass sie absterben. Oxaliplatin ist eine Platinverbindung mit Diaminocyclohexan-Rest; ihre aktiven Abbauprodukte vernetzen DNA-Stränge und hemmen so DNA-Synthese und Zellteilung. Die Wirkung ergänzt sich mit 5-Fluorouracil. Typisch sind kälteausgelöste Nervenreizungen kurz nach der Infusion und eine mit der Gesamtdosis zunehmende Nervenschädigung.","nebenwirkungen":{"sehrHaeufig":["Periphere sensorische Neuropathie (Kribbeln, Taubheit, Kälteempfindlichkeit)","Neutropenie, Thrombozytopenie, Anämie","Übelkeit, Erbrechen, Durchfall","Stomatitis (Mundschleimhautentzündung)","Müdigkeit, Fieber","Allergische Reaktionen","Erhöhte Leberwerte","Infektionen"],"haeufig":["Laryngopharyngeale Dysästhesie (Engegefühl im Hals, Schluck- oder Atembeschwerden, meist kälteausgelöst)","Dehydratation (Flüssigkeitsmangel)","Hypokaliämie (Kaliummangel)","Thrombosen, Lungenembolie","Depression, Schlaflosigkeit","Haarausfall"],"gelegentlich":["Ileus (Darmverschluss)","Metabolische Azidose (Übersäuerung)"],"selten":["Anaphylaxie (schwere allergische Reaktion bis zum Schock)","Interstitielle Lungenerkrankung, Lungenfibrose","Hörverlust","Immunhämolytische Anämie und Immunthrombozytopenie","Kolitis inkl. Clostridioides-difficile-Durchfall","Posteriores reversibles Enzephalopathie-Syndrom (PRES)"],"sehrSelten":["Hämolytisch-urämisches Syndrom","Leberschäden (sinusoidales Obstruktionssyndrom)"],"unbekannt":["QT-Verlängerung, Torsade de pointes","Rhabdomyolyse (Muskelzerfall)","Herzinfarkt, Krampfanfälle"]},"schwangerschaft":"Nicht anwenden, da Fruchtschäden möglich sind. Frauen sollen während und bis 9 Monate, Männer bis 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["In den Tagen nach der Infusion Kälte meiden: keine kalten Getränke, kein Eis, Handschuhe beim Berühren kalter Gegenstände.","Kribbeln oder Taubheit, die zwischen den Zyklen anhält, melden – die Dosis wird dann angepasst.","Fahrtüchtigkeit kann durch Schwindel oder Sehstörungen eingeschränkt sein."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"oxazepam":{"wirkmechanismus":"Wirkt angstlösend, beruhigend und schlaffördernd. Oxazepam verstärkt über die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors die Wirkung des hemmenden Botenstoffs GABA. Es wird ohne Beteiligung der Cytochrom-P450-Enzyme direkt an Glucuronsäure gekoppelt und über die Niere ausgeschieden; es entstehen keine wirksamen Abbauprodukte, weshalb es sich auch bei älteren Menschen kaum anreichert.","nebenwirkungen":{"haeufig":["Müdigkeit, Schläfrigkeit, Benommenheit (auch am Folgetag)","Schwindel","Muskelschwäche, Gangunsicherheit"],"unbekannt":["Anterograde Amnesie (Gedächtnislücken)","Verwirrtheit, verlangsamte Reaktion","Paradoxe Reaktionen (Unruhe, Aggressivität, Halluzinationen)","Atemdepression","Abhängigkeit, Entzugssymptome und Rebound-Schlaflosigkeit beim Absetzen","Stürze, v. a. bei älteren Menschen","Allergische Hautreaktionen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Bei Anwendung gegen Ende der Schwangerschaft können beim Neugeborenen Muskelschlaffheit, Atemprobleme, Unterkühlung und Entzugssymptome auftreten.","stillzeit":"Oxazepam geht in geringen Mengen in die Muttermilch über. Nicht empfohlen; höchstens ausnahmsweise nach ärztlicher Abwägung.","hinweise":["So kurz wie möglich anwenden (bei Schlafstörungen höchstens 4 Wochen, bei Angst höchstens 8–12 Wochen, jeweils einschliesslich Ausschleichen).","Nach längerer Einnahme nicht abrupt absetzen, sondern langsam ausschleichen.","Kein Alkohol; die Fahrtüchtigkeit kann auch noch am Folgetag beeinträchtigt sein.","Ältere Menschen: erhöhte Sturzgefahr, besonders nachts."],"darreichung":["Tabletten"]},"oxcarbazepin":{"wirkmechanismus":"Beruhigt überaktive Nervenzellen und verhindert so die Ausbreitung von Krampfanfällen. Oxcarbazepin ist ein Prodrug: Es wird rasch zum wirksamen Monohydroxy-Derivat (MHD, Licarbazepin) umgewandelt, das spannungsabhängige Natriumkanäle blockiert und so hochfrequente Entladungen von Nervenzellen hemmt. Anders als Carbamazepin wird es kaum über CYP-Enzyme abgebaut; es induziert CYP3A4 nur mässig und hemmt CYP2C19.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Kopfschmerzen, Schwindel","Doppelbilder","Übelkeit, Erbrechen","Müdigkeit"],"haeufig":["Hyponatriämie (Natriummangel)","Unruhe, Stimmungsschwankungen, Verwirrtheit, Depression, Apathie","Gang- und Koordinationsstörungen (Ataxie), Zittern, Augenzittern, Konzentrations- und Gedächtnisstörungen","Verschwommenes Sehen, Drehschwindel","Durchfall, Verstopfung, Bauchschmerzen","Hautausschlag, Haarausfall, Akne","Schwächegefühl"],"gelegentlich":["Leukopenie (Mangel an weissen Blutkörperchen)","Nesselsucht","Erhöhte Leberwerte"],"sehrSelten":["Thrombozytopenie (Mangel an Blutplättchen)","Multiorgan-Überempfindlichkeitsreaktion (DRESS), Angioödem","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Herzrhythmusstörungen (AV-Block)","Hepatitis","Pankreatitis (Entzündung der Bauchspeicheldrüse)","Lupus-erythematodes-ähnliches Syndrom"],"unbekannt":["Agranulozytose, aplastische Anämie, Panzytopenie","Anaphylaxie (schwere allergische Reaktion)","Schilddrüsenunterfunktion","Inadäquate ADH-Sekretion (SIADH)","Verminderte Knochendichte, Stürze","Sprachstörungen"]},"schwangerschaft":"Nur nach sorgfältiger ärztlicher Abwägung; nicht eigenmächtig absetzen. Möglichst Monotherapie in niedrigster wirksamer Dosis, Folsäure-Einnahme vor und während der Schwangerschaft; Spiegel können in der Schwangerschaft sinken.","stillzeit":"Geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung und unter Beobachtung des Kindes auf Schläfrigkeit.","hinweise":["Natrium im Blut vor Behandlungsbeginn und regelmässig kontrollieren, besonders bei älteren Menschen; Warnzeichen sind Müdigkeit, Verwirrtheit, Übelkeit und vermehrte Anfälle.","Bei Hautausschlag, Fieber oder Schleimhautblasen sofort ärztlich melden.","Nicht abrupt absetzen – Gefahr von Krampfanfällen.","Alkohol meiden; Vorsicht beim Autofahren."],"darreichung":["Filmtabletten","Retardtabletten","Suspension zum Einnehmen"]},"oxerutine":{"wirkmechanismus":"Dichtet die kleinsten Blutgefässe ab und vermindert so Schwellungen in den Beinen. Oxerutine sind halbsynthetische Abkömmlinge des Pflanzenflavonoids Rutin, vor allem Troxerutin. Sie lagern sich in die Gefässwand ein, verringern die krankhaft erhöhte Durchlässigkeit und Brüchigkeit der Kapillaren und damit den Austritt von Flüssigkeit und Eiweiss ins Gewebe. Zudem verbessern sie die Mikrozirkulation und schützen die Gefässinnenwand vor oxidativen Schäden.","nebenwirkungen":{"selten":["Magen-Darm-Beschwerden wie Blähungen, Durchfall, Bauchschmerzen, Übelkeit","Kopfschmerzen, Schwindel, Müdigkeit","Hautausschlag, Juckreiz, Nesselsucht","Hitzegefühl mit Gesichtsrötung (Flush)"],"sehrSelten":["Schwere allergische (anaphylaktische) Reaktionen"],"unbekannt":["Gel: Hautreaktionen an der Auftragsstelle (Rötung, Juckreiz)"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel vorsichtshalber nicht einnehmen; danach nur nach ärztlicher Rücksprache.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; nur nach ärztlicher Rücksprache anwenden.","hinweise":["Tabletten zu den Mahlzeiten einnehmen; die Wirkung setzt nach einigen Tagen bis Wochen ein.","Gel mehrmals täglich auf die betroffenen Stellen auftragen und sanft einmassieren; vor dem Anziehen von Kompressionsstrümpfen einziehen lassen.","Bewegung, Hochlagern der Beine und Kompressionsstrümpfe unterstützen die Behandlung."],"darreichung":["Filmtabletten","Gel"]},"oxiconazol":{"wirkmechanismus":"Bekämpft Hautpilze, indem es den Aufbau ihrer Zellmembran stört. Oxiconazol hemmt das pilzeigene Enzym Lanosterol-14-alpha-Demethylase und damit die Bildung von Ergosterol; die Pilzmembran wird geschädigt. Es wirkt gegen Fadenpilze, Hefen und Schimmelpilze sowie gegen einige grampositive Bakterien. Der Wirkstoff reichert sich in der Hornschicht an, sodass meist eine tägliche Anwendung genügt.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Rötung an der Anwendungsstelle","Hauttrockenheit, Schuppung","Allergische Kontaktdermatitis"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; im ersten Drittel vorsichtshalber nicht, später nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nur nach ärztlicher Abwägung; nicht im Brustbereich auftragen.","hinweise":["Behandlung nach Abklingen der Beschwerden noch etwa 2 Wochen fortsetzen, um Rückfälle zu vermeiden.","Haut vor dem Auftragen reinigen und gut trocknen; Handtücher und Socken häufig wechseln.","Nicht in die Augen oder auf Schleimhäute bringen."],"darreichung":["Creme","Lösung"]},"oxybuprocain":{"wirkmechanismus":"Betäubt die Oberfläche von Horn- und Bindehaut innert kurzer Zeit für etwa eine Viertelstunde. Oxybuprocain blockiert spannungsabhängige Natriumkanäle der Nervenfasern und unterbricht so die Weiterleitung von Schmerzreizen. Als Ester-Lokalanästhetikum wird es durch Esterasen abgebaut.","nebenwirkungen":{"unbekannt":["Vorübergehendes Brennen und Stechen beim Eintropfen","Bindehautrötung, Tränenfluss","Hornhautschäden (Epitheldefekte, Keratitis, Trübung, Geschwür), vor allem bei wiederholter Anwendung","Allergische Reaktionen (Kontaktdermatitis, Lidschwellung)"]},"schwangerschaft":"Eine einmalige Anwendung bei Untersuchungen ist nach ärztlicher Abwägung möglich; Daten fehlen.","stillzeit":"Eine einmalige Anwendung ist nach ärztlicher Abwägung möglich; Daten fehlen.","hinweise":["Nach der Untersuchung die Augen nicht reiben, bis das Gefühl zurückgekehrt ist.","Nicht zur Selbstbehandlung von Augenschmerzen verwenden – wiederholte Anwendung schädigt die Hornhaut."],"darreichung":["Augentropfen"]},"oxybutynin":{"wirkmechanismus":"Entspannt den Blasenmuskel, sodass die Blase mehr Urin fassen kann und der Harndrang seltener und schwächer wird. Oxybutynin blockiert Muskarinrezeptoren (vor allem M1 und M3) am Blasenmuskel (Detrusor) und wirkt zusätzlich direkt krampflösend auf die glatte Muskulatur. Beim Einnehmen entsteht durch Abbau in Darmwand und Leber (CYP3A4) der ebenfalls stark anticholinerg wirkende Metabolit N-Desethyloxybutynin, der vor allem die Mundtrockenheit verursacht; beim Pflaster entsteht davon weniger. Oxybutynin gelangt ins Gehirn und kann dort Müdigkeit und Verwirrtheit auslösen.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Verstopfung","Übelkeit","Schwindel, Kopfschmerzen, Schläfrigkeit","Trockene Haut","Juckreiz und Rötung an der Klebestelle (Pflaster)"],"haeufig":["Verwirrtheit","Durchfall, Erbrechen","Trockene Augen","Verschwommenes Sehen","Harnverhalt","Gesichtsrötung (Flush)"],"gelegentlich":["Bauchbeschwerden, Appetitlosigkeit, Schluckbeschwerden"],"unbekannt":["Unruhe, Angst, Halluzinationen, Albträume, Paranoia","Kognitive Störungen bei älteren Menschen","Krampfanfälle","Erweiterte Pupillen, Auslösung eines Engwinkelglaukoms","Herzrasen, Herzrhythmusstörungen","Verminderte Schweissbildung, Hitzschlag","Angioödem, Nesselsucht, Lichtempfindlichkeit","Harnwegsinfektionen","Reflux, Pseudo-Obstruktion des Darms bei Risikopatienten","Erektionsstörungen"]},"schwangerschaft":"Nicht anwenden, ausser wenn eindeutig erforderlich – zur Sicherheit in der Schwangerschaft liegen keine ausreichenden Daten vor.","stillzeit":"Nicht empfohlen – Oxybutynin kann in die Muttermilch übergehen und die Milchbildung hemmen.","hinweise":["Kann Schläfrigkeit und verschwommenes Sehen verursachen: Vorsicht beim Autofahren und Bedienen von Maschinen; Alkohol verstärkt die Müdigkeit.","Bei Hitze, Sport oder Fieber auf ausreichende Abkühlung achten, da weniger geschwitzt wird.","Wegen Mundtrockenheit auf gute Zahnpflege achten (Kariesrisiko).","Pflaster zweimal wöchentlich auf saubere, trockene Haut von Bauch, Hüfte oder Gesäss kleben und die Klebestelle jedes Mal wechseln."],"darreichung":["Tabletten","Transdermales Pflaster"]},"oxycodon":{"wirkmechanismus":"Lindert starke Schmerzen, indem es an die körpereigenen Opioid-Andockstellen in Gehirn und Rückenmark bindet. Oxycodon ist ein halbsynthetischer Agonist vor allem am μ-Opioidrezeptor und hemmt Weiterleitung und Wahrnehmung von Schmerzreizen. Der Abbau erfolgt in der Leber überwiegend über CYP3A4 zu Noroxycodon und in geringem Mass über CYP2D6 zu Oxymorphon; deshalb beeinflussen CYP3A4-Hemmer und -Induktoren die Wirkung deutlich.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schwindel, Kopfschmerzen","Obstipation (Verstopfung)","Übelkeit, Erbrechen","Juckreiz"],"haeufig":["Appetitlosigkeit","Angst, Verwirrtheit, Depression, Schlafstörungen","Zittern, Benommenheit","Atemnot","Bauchschmerzen, Durchfall, Mundtrockenheit, Verdauungsbeschwerden","Hautausschlag, Schwitzen","Schwäche, Müdigkeit"],"gelegentlich":["Atemdepression (abgeschwächte Atmung)","Überempfindlichkeitsreaktionen","Halluzinationen, Euphorie","Krampfanfälle, Ohnmacht","Herzrasen","Ileus (Darmlähmung)","Harnverhalt, Erektionsstörung","Abhängigkeit und Entzugssymptome"],"selten":["Blutdruckabfall, Schwindel beim Aufstehen","Nesselsucht"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Aggression","Hyperalgesie (erhöhte Schmerzempfindlichkeit)","Gallenkoliken, Cholestase (Gallenstau)","Schlafapnoe","Ausbleiben der Regel"]},"schwangerschaft":"Möglichst nicht anwenden; nur nach strenger ärztlicher Abwägung. Längere Anwendung kann beim Neugeborenen ein Entzugssyndrom, Anwendung unter der Geburt eine Atemdepression auslösen.","stillzeit":"Oxycodon geht in die Muttermilch über und kann beim Säugling Atemdepression verursachen; während der Behandlung nicht stillen.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern – sonst Gefahr einer lebensbedrohlichen Überdosierung.","Kein Alkohol und kein Grapefruitsaft; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Gegen Verstopfung von Beginn an vorbeugen (Abführmittel, ausreichend trinken).","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome)."],"darreichung":["Retardtabletten","Kapseln","Schmelztabletten","Lösung zum Einnehmen","Injektionslösung"]},"oxycodon-naloxon":{"wirkmechanismus":"Lindert starke Schmerzen und verursacht dabei weniger Verstopfung als ein Opioid allein. Oxycodon wirkt als Agonist an μ-Opioidrezeptoren in Gehirn und Rückenmark. Naloxon blockiert dieselben Rezeptoren, wird nach dem Schlucken aber zu über 97 % bereits bei der ersten Leberpassage abgebaut. Es wirkt deshalb fast nur im Darm, wo es die verstopfende Wirkung von Oxycodon abschwächt, ohne die Schmerzlinderung wesentlich zu beeinträchtigen.","nebenwirkungen":{"haeufig":["Appetitlosigkeit","Schlaflosigkeit","Schwindel, Kopfschmerzen, Schläfrigkeit","Hitzewallungen","Bauchschmerzen, Verstopfung, Durchfall, Blähungen","Übelkeit, Erbrechen, Mundtrockenheit, Verdauungsbeschwerden","Juckreiz, Hautreaktionen, Schwitzen","Schwäche, Müdigkeit"],"gelegentlich":["Überempfindlichkeitsreaktionen","Angst, Verwirrtheit, Unruhe, Depression","Krampfanfälle, Ohnmacht, Zittern","Angina pectoris (Brustenge) bei vorbestehender koronarer Herzkrankheit","Blutdruckabfall oder -anstieg","Atemnot, Husten","Gallenkoliken, erhöhte Leberwerte","Entzugssymptome"],"selten":["Herzrasen"],"unbekannt":["Atemdepression (abgeschwächte Atmung)","Schlafapnoe","Euphorie, Halluzinationen, Albträume, Aggression","Harnverhalt","Abhängigkeit"]},"schwangerschaft":"Möglichst nicht anwenden; nur nach strenger ärztlicher Abwägung. Längere Anwendung kann beim Neugeborenen ein Entzugssyndrom auslösen.","stillzeit":"Oxycodon geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern; zerkleinert, geschnupft oder gespritzt drohen Überdosierung oder akuter Entzug.","Kein Alkohol und kein Grapefruitsaft; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Bei Umstellung von einem anderen Opioid können anfangs Durchfall und Entzugssymptome auftreten.","Nach längerer Anwendung nicht abrupt absetzen."],"darreichung":["Retardtabletten"]},"oxymetazolin":{"wirkmechanismus":"Lässt die geschwollene Nasenschleimhaut innerhalb weniger Minuten abschwellen. Oxymetazolin stimuliert Alpha-Adrenozeptoren an den Blutgefässen der Nasenschleimhaut und verengt sie; Blutfülle und Schwellung nehmen ab, die Nasenatmung wird freier. Die Wirkung hält bis etwa 12 Stunden an. Bei Daueranwendung lässt die Wirkung nach und es kann eine reaktive Schleimhautschwellung entstehen (Rhinitis medicamentosa).","nebenwirkungen":{"haeufig":["Brennen oder Trockenheit der Nasenschleimhaut","Niesen"],"gelegentlich":["Verstärkte Nasenverstopfung nach Abklingen der Wirkung (reaktive Hyperämie)","Nasenbluten"],"selten":["Herzklopfen, beschleunigter Puls","Blutdruckanstieg"],"sehrSelten":["Unruhe, Schlaflosigkeit, Müdigkeit, Kopfschmerzen","Halluzinationen und Krampfanfälle, vor allem bei Kindern","Herzrhythmusstörungen","Atemstillstand (Apnoe) bei Säuglingen und Neugeborenen nach Überdosierung"]},"schwangerschaft":"Nur nach ärztlicher Abwägung und nicht über der empfohlenen Dosis, da eine Gefässverengung im ganzen Körper möglich ist.","stillzeit":"Nur nach ärztlicher Abwägung; die empfohlene Dosis nicht überschreiten.","hinweise":["Ohne ärztlichen Rat höchstens 5–7 Tage anwenden, sonst droht ein Gewöhnungseffekt mit dauerhaft verstopfter Nase.","Für Säuglinge und Kinder nur die altersgerechte Stärke verwenden; eine Überdosierung kann bei Kleinkindern gefährlich sein.","Aus hygienischen Gründen jede Packung nur von einer Person verwenden."],"darreichung":["Nasenspray","Nasentropfen"]},"oxytocin":{"wirkmechanismus":"Löst Wehen aus bzw. verstärkt sie und lässt die Gebärmutter nach der Geburt fest zusammenziehen, was Blutungen vermindert. Oxytocin ist ein synthetisch hergestelltes Hormon, das dem körpereigenen Hormon des Hypophysenhinterlappens entspricht. Es bindet an Oxytocin-Rezeptoren der Gebärmuttermuskulatur, deren Zahl gegen Ende der Schwangerschaft stark zunimmt, und steigert über einen Calcium-Einstrom Häufigkeit und Kraft der Kontraktionen. Zusätzlich fördert es den Milchfluss und wirkt in hoher Dosis schwach antidiuretisch (Wasserretention).","nebenwirkungen":{"haeufig":["Kopfschmerzen","Beschleunigter oder verlangsamter Herzschlag","Übelkeit, Erbrechen"],"gelegentlich":["Herzrhythmusstörungen"],"selten":["Anaphylaktische bzw. anaphylaktoide Reaktionen mit Atemnot, Blutdruckabfall oder Schock","Hautausschlag"],"unbekannt":["Wasservergiftung mit Hyponatriämie (Kopfschmerzen, Krampfanfälle, Koma) bei hoher Dosis und viel Infusionsflüssigkeit","Akuter Blutdruckabfall mit Gesichtsrötung (Flush) nach rascher Injektion","Myokardischämie (Durchblutungsstörung des Herzens), QT-Verlängerung","Lungenödem","Disseminierte intravasale Gerinnung (Verbrauchskoagulopathie)","Angioödem","Überstimulation der Gebärmutter (Dauerkontraktion) bis zum Gebärmutterriss","Beim Kind: Sauerstoffmangel und Herzfrequenzstörungen; Gelbsucht und Netzhautblutungen beim Neugeborenen"]},"schwangerschaft":"Nur unter der Geburt bzw. unmittelbar danach im Spital unter Überwachung von Wehen und kindlichen Herztönen anzuwenden; zu anderen Zeitpunkten der Schwangerschaft nicht anwenden.","stillzeit":"Geht in kleinen Mengen in die Muttermilch über, wird aber im Magen-Darm-Trakt des Säuglings rasch abgebaut; Stillen ist möglich.","hinweise":["Wird nur im Spital von Fachpersonen verabreicht, meist als langsame, genau dosierte Infusion mit fortlaufender CTG-Überwachung.","Bei starken Kopfschmerzen, Verwirrtheit, Atemnot, Brustschmerzen oder Herzklopfen sofort das Behandlungsteam informieren."],"darreichung":["Injektionslösung (Ampullen, zur Infusion oder Injektion)"]},"ozanimod":{"wirkmechanismus":"Hält bestimmte weisse Blutkörperchen in den Lymphknoten zurück, so dass weniger Entzündungszellen ins Nervensystem bzw. in die Darmschleimhaut gelangen. Ozanimod bindet mit hoher Affinität an die Sphingosin-1-Phosphat-Rezeptoren S1P1 und S1P5 und bewirkt die Internalisierung von S1P1 auf Lymphozyten. Die Zahl der Lymphozyten im Blut sinkt dadurch etwa um die Hälfte; die Wirkung wird zu einem grossen Teil von aktiven Metaboliten getragen. Eine langsame Dosissteigerung in der ersten Woche mildert die anfängliche Pulsverlangsamung.","nebenwirkungen":{"sehrHaeufig":["Nasen-Rachen-Entzündung (Erkältung)","Lymphopenie (Mangel an Lymphozyten)"],"haeufig":["Halsentzündung, virale Atemwegsinfekte, Harnwegsinfekte","Gürtelrose (Herpes zoster) und Lippenherpes","Kopfschmerzen","Pulsverlangsamung (Bradykardie)","Bluthochdruck","Schwindel beim Aufstehen (orthostatische Hypotonie)","Erhöhte Leberwerte (ALT, GGT)","Periphere Ödeme (Wassereinlagerungen)"],"gelegentlich":["Makulaödem (Schwellung der Netzhautmitte)","Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht)"],"unbekannt":["PML und Kryptokokken-Infektionen","Hautkrebs (z. B. Basalzellkarzinom, Melanom)","PRES (posteriores reversibles Enzephalopathie-Syndrom)","Schwere Verschlechterung der MS nach dem Absetzen"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und bis 3 Monate nach dem Absetzen zuverlässig verhüten.","stillzeit":"Nicht stillen während der Behandlung.","hinweise":["Einschleichende Dosierung über 7 Tage; nach einem Therapieunterbruch (je nach Dauer) erneut einschleichend beginnen.","EKG vor Beginn; Blutbild, Leberwerte und Blutdruck regelmässig kontrollieren.","Nicht eigenmächtig absetzen; bei Sehstörungen, Fieber oder neuen neurologischen Beschwerden ärztlich abklären lassen."],"darreichung":["Hartkapseln"]}});
